/* The knob pictures. art.c is generated by tools/make_art.py: do not edit it by hand.
 *
 * A picture: w x h pixels, 4 bits a pixel (16 colours), rows top to bottom, two pixels a byte, the HIGH
 * nibble first (the left pixel); a row starts on a byte. pal[] holds the 16 colours as RGB565 values
 * (plain numbers: the module swaps the bytes for the panel). Colour 0 is the background the picture sits on.
 * There is no pointer in the picture: the module draws it at run time, from the centre (cx, cy), between
 * radius r0 and r1, at the angle of the value (-135 degrees .. +135 degrees, 0 = straight up). */
#ifndef CB_ART_H
#define CB_ART_H
#include <stdint.h>

typedef struct {
    uint16_t w, h;
    uint16_t cx, cy;        /* the knob's centre in the picture */
    uint16_t r0, r1;        /* the pointer runs from r0 to r1 from the centre */
    uint16_t pointer;       /* the pointer's colour, RGB565 */
    uint16_t pad;
    const uint16_t *pal;    /* 16 colours, RGB565 */
    const uint8_t *px;      /* (w + 1) / 2 * h bytes */
} cb_img_t;

extern const cb_img_t CB_ART_MORE;      /* 112 x 112: the big MORE knob, its skirt and 7 tick marks */
extern const cb_img_t CB_ART_SMALL;     /* 44 x 44: the FEVER / PRESCRIPTION knob, no ticks */

/* the panel's colours (RGB565), shared by the art and the module's drawing */
#define CB_COL_PANEL  0xEC96u           /* (237,147,177): the light pink panel, behind the small knobs */
#define CB_COL_MORE   0xD28Fu           /* (212, 83,126): the darker square behind the MORE knob */

#endif
